-- schema.sql: the current ledger schema, for reading. The migrations in ledger/migrations/
-- are what actually run; keep this file equal to the result of applying all of them.

-- 001_initial: the ledger. Three tables plus indexes.
-- Portable SQL: TEXT / INTEGER / REAL only; JSON stored as TEXT; timestamps are ISO-8601 UTC text.
-- @@AUTOINCREMENT@@ is replaced by migrate.py per dialect:
--   SQLite   -> AUTOINCREMENT
--   Postgres -> GENERATED BY DEFAULT AS IDENTITY

CREATE TABLE IF NOT EXISTS runs (
  id            INTEGER PRIMARY KEY @@AUTOINCREMENT@@,
  component     TEXT NOT NULL,
  portal        TEXT,
  started_at    TEXT NOT NULL,
  finished_at   TEXT,
  status        TEXT NOT NULL CHECK (status IN ('running', 'completed', 'skipped_timeout', 'error')),
  stage_counts  TEXT,
  error         TEXT,
  log_path      TEXT,
  dry_run       INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS calls (
  id                TEXT PRIMARY KEY,
  portal            TEXT NOT NULL,
  title             TEXT,
  type              TEXT,
  department        TEXT,
  naics_code        TEXT,
  set_aside         TEXT,
  posted_date       TEXT,
  due_date          TEXT,
  description       TEXT,
  url               TEXT,
  source_type       TEXT,
  first_seen_at     TEXT NOT NULL,
  last_seen_at      TEXT NOT NULL,
  first_run_id      INTEGER,
  last_run_id       INTEGER,
  filter_result     TEXT NOT NULL DEFAULT 'pending' CHECK (filter_result IN ('pending', 'kept', 'rejected')),
  filter_reason     TEXT,
  match_tier        TEXT,
  matched_keywords  TEXT,
  ai_verdict        TEXT CHECK (ai_verdict IS NULL OR ai_verdict IN ('yes', 'no', 'maybe')),
  ai_reasoning      TEXT,
  reviewed_at       TEXT,
  slack_channel     TEXT,
  slack_ts          TEXT,
  posted_at         TEXT,
  human_status      TEXT CHECK (human_status IS NULL OR human_status IN ('pursue', 'not_relevant', 'submitted', 'dismissed')),
  human_by          TEXT,
  human_at          TEXT,
  human_notes       TEXT,
  extra             TEXT,
  updated_at        TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS proposals (
  submission_id     TEXT PRIMARY KEY,
  title             TEXT,
  portal            TEXT,
  agency            TEXT,
  solicitation_id   TEXT,
  type              TEXT,
  role              TEXT,
  partners          TEXT,
  submitted_date    TEXT,
  due_date          TEXT,
  requested_value   TEXT,
  outcome           TEXT CHECK (outcome IS NULL OR outcome IN ('won', 'lost', 'no_award', 'pending', 'withdrawn', 'shortlisted')),
  outcome_date      TEXT,
  award_value       TEXT,
  strength_rating   INTEGER CHECK (strength_rating IS NULL OR strength_rating BETWEEN 1 AND 5),
  strength_reason   TEXT,
  why_won_or_lost   TEXT,
  use_as_exemplar   INTEGER NOT NULL DEFAULT 0,
  themes            TEXT,
  drive_link        TEXT,
  brief             TEXT,
  synced_at         TEXT,
  updated_at        TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_calls_portal_first_seen ON calls (portal, first_seen_at);
CREATE INDEX IF NOT EXISTS idx_calls_human_status      ON calls (human_status);
CREATE INDEX IF NOT EXISTS idx_calls_ai_verdict        ON calls (ai_verdict);
CREATE INDEX IF NOT EXISTS idx_proposals_portal_outcome ON proposals (portal, outcome);
